CREATE TABLE T_PARAMETROS_ESTACIONAMENTO (
    NR_MINUTOS_TEMPO_LIVRE  NUMBER          NOT NULL,
	VL_MINUTO_VAGA	NUMBER(5,2),
	DT_INICIO_VIGENCIA DATE NOT NULL,
	DT_TERMINO_VIGENCIA DATE
);

-- Vamos inserir 1 linha e deixar a data de termino de vigencia sem conte�do (nulo),
-- informando assim que esses valores s�o os atuais.

--------------------------------------------------------------------------------
-- Tabela T_VAGA, onde temos o cadastro das vagas de estacionamento monitoradas
--------------------------------------------------------------------------------
CREATE TABLE T_VAGA (
    ID_VAGA         NUMBER          NOT NULL,
    CD_SENSOR       VARCHAR2(20)    NOT NULL,
    NR_VAGA         VARCHAR2(10)    NOT NULL,
    DS_LOGRADOURO   VARCHAR2(100)   NOT NULL,
    DS_REGIAO       VARCHAR2(50)    NOT NULL,
    TP_VAGA         VARCHAR2(10)    NOT NULL,
    FL_ATIVA        CHAR(1)         NOT NULL,
    CONSTRAINT PK_T_VAGA PRIMARY KEY (ID_VAGA),
    CONSTRAINT UK_T_VAGA_SENSOR UNIQUE (CD_SENSOR, NR_VAGA),
    CONSTRAINT CK_T_VAGA_TP_VAGA CHECK (TP_VAGA IN ('COMUM','IDOSO','PCD')),
    CONSTRAINT CK_T_VAGA_FL_ATIVA CHECK (FL_ATIVA IN ('S','N'))
);

CREATE SEQUENCE SEQ_T_VAGA
    START WITH 1
    INCREMENT BY 1
    NOCACHE
    NOCYCLE;


--------------------------------------------------------------------------------
-- Tabela T_STG_EVENTO_SENSOR_VAGA, onde temos os dados brutos fornecidos
-- por cada sensor inteligente, cadastrado para cada vaga.
--------------------------------------------------------------------------------
CREATE TABLE T_STG_EVENTO_SENSOR_VAGA (
    ID_EVENTO_SENSOR   NUMBER          NOT NULL,
    CD_SENSOR          VARCHAR2(20)    NOT NULL,
    NR_VAGA            VARCHAR2(10)    NOT NULL,
    ST_VAGA            VARCHAR2(1)     NOT NULL,
    DT_EVENTO          DATE            NOT NULL,
    NR_PLACA_VEICULO   VARCHAR2(10)	   NOT NULL,
    DT_CARGA           DATE            NOT NULL,
	FL_PROCESSADO 		CHAR(1) DEFAULT 'N' NOT NULL,
    CONSTRAINT PK_T_STG_EVT_SENSOR PRIMARY KEY (ID_EVENTO_SENSOR),
    CONSTRAINT CK_T_STG_ST_VAGA CHECK (ST_VAGA IN ('O','S')),
	CONSTRAINT CK_T_STG_FL_PROCESSADO CHECK (FL_PROCESSADO IN ('N','S','E'))
);

-- ST_VAGA = 'O' significa que o ve�culo chegou e estacionou na vaga e 'S' significa que ele saiu da vaga.
-- FL_PROCESSADO somente com os valores: N = N�o processado | S = Processado com sucesso | E = Processado com erro
--

CREATE SEQUENCE SEQ_T_STG_EVENTO_SENSOR_VAGA
    START WITH 1
    INCREMENT BY 1
    NOCACHE
    NOCYCLE;

--------------------------------------------------------------------------------
-- Tabela T_PERMANENCIA_VEICULO, onde temos o c�lculo de tempo da perman�ncia calculada
--------------------------------------------------------------------------------
CREATE TABLE T_PERMANENCIA_VEICULO (
    ID_PERMANENCIA              NUMBER          NOT NULL,
    CD_SENSOR                   VARCHAR2(20)    NOT NULL,
    NR_VAGA                     VARCHAR2(10)    NOT NULL,
	NR_PLACA_VEICULO 			VARCHAR2(10)		NULL,
    DT_ENTRADA                  DATE            NOT NULL,
    DT_SAIDA                    DATE,
    NR_TEMPO_PERMANENCIA_MIN    NUMBER,
    DT_PROCESSAMENTO            DATE            NOT NULL,
    CONSTRAINT PK_T_PERMANENCIA_VEIC PRIMARY KEY (ID_PERMANENCIA),
    CONSTRAINT FK_T_PERM_VAGA FOREIGN KEY (CD_SENSOR, NR_VAGA)
        REFERENCES T_VAGA (CD_SENSOR, NR_VAGA)
);

CREATE SEQUENCE SEQ_T_PERMANENCIA_VEICULO
    START WITH 1
    INCREMENT BY 1
    NOCACHE
    NOCYCLE;

--------------------------------------------------------------------------------
-- Tabela T_COBRANCA_VAGA, onde temos a cobran�a gerada
--------------------------------------------------------------------------------
CREATE TABLE T_COBRANCA_VAGA (
    ID_COBRANCA             NUMBER          NOT NULL,
    ID_PERMANENCIA          NUMBER          NOT NULL,
    NR_MINUTOS_EXCEDENTES   NUMBER          NOT NULL,
    VL_COBRANCA             NUMBER(10,2)    NOT NULL,
    ST_COBRANCA             VARCHAR2(1)     NOT NULL,
	DT_VENCIMENTO			DATE			NOT NULL,
    DT_GERACAO              DATE            NOT NULL,
    CONSTRAINT PK_T_COBRANCA_VAGA PRIMARY KEY (ID_COBRANCA),
    CONSTRAINT FK_T_COBR_PERMANENCIA FOREIGN KEY (ID_PERMANENCIA)
        REFERENCES T_PERMANENCIA_VEICULO (ID_PERMANENCIA),
    CONSTRAINT CK_T_COBR_ST_COBRANCA CHECK (ST_COBRANCA IN ('A','P','G','C'))
);

CREATE SEQUENCE SEQ_T_COBRANCA_VAGA
    START WITH 1
    INCREMENT BY 1
    NOCACHE
    NOCYCLE;

-- ============================================================
-- T_LOG_ERRO_EVENTO - Log de inconsist�ncias (apoio � RN06/RN11)
-- ============================================================
-- Toda vez que um evento da stage n�o puder ser processado
-- (status inv�lido, sensor n�o cadastrado, evento fora de
-- sequ�ncia, etc.), gravamos aqui o motivo, permitindo auditoria
-- posterior sem travar o processamento dos demais eventos.

CREATE TABLE T_LOG_ERRO_EVENTO (
    ID_LOG              NUMBER          NOT NULL,
    ID_EVENTO_SENSOR    NUMBER          NOT NULL,
    DS_MOTIVO_ERRO      VARCHAR2(200)   NOT NULL,
    DT_OCORRENCIA       DATE            NOT NULL,
    CONSTRAINT PK_T_LOG_ERRO_EVENTO PRIMARY KEY (ID_LOG)
);

CREATE SEQUENCE SEQ_T_LOG_ERRO_EVENTO
    START WITH 1
    INCREMENT BY 1
    NOCACHE
    NOCYCLE;

